script:
const wrapper = root_element.querySelector(".qr-wrapper");
const re_generate = root_element.querySelector("#re_generate");

function generate_qr_code() {
	wrapper.innerHTML = `<p>Generating QR...</p>`;

	frappe.call({
		method: "hrmsadapter.api.v1.QR_code_generator.generate_qr_code",
		args: {
			name: "HRMS Mobile Settings",
			company: frappe.defaults.get_default("company"),
			server_url: window.location.origin,
			expiry_in_minutes: 5,
		},
		callback(r) {
			if (r.message) {
				wrapper.innerHTML = `
					<div style="text-align:center;">
						<img
							src="data:image/png;base64,${r.message}"
							width="220"
						>
					</div>
				`;
			}
		},
	});
}

// Generate QR when Workspace block loads
generate_qr_code();

// Regenerate QR on button click
re_generate.addEventListener("click", generate_qr_code);
